CREATE TABLE forecast_history (
    forecaster_id TEXT NOT NULL,
    domain TEXT NOT NULL,
    forecast_count INTEGER NOT NULL DEFAULT 0 CHECK(forecast_count>=0),
    brier_sum REAL NOT NULL DEFAULT 0 CHECK(brier_sum>=0),
    last_brier REAL,
    last_resolved_at TEXT,
    PRIMARY KEY(forecaster_id, domain)
);
CREATE TABLE forecast_resolutions (
    resolution_id TEXT PRIMARY KEY,
    forecast_id TEXT NOT NULL,
    forecaster_id TEXT NOT NULL,
    domain TEXT NOT NULL,
    probability REAL NOT NULL CHECK(probability>=0 AND probability<=1),
    outcome INTEGER NOT NULL CHECK(outcome IN (0,1)),
    brier_score REAL NOT NULL CHECK(brier_score>=0 AND brier_score<=1),
    resolved_at TEXT NOT NULL,
    UNIQUE(forecast_id, forecaster_id)
);
CREATE TABLE intent_genomes (
    genome_id TEXT NOT NULL,
    owner TEXT NOT NULL,
    version INTEGER NOT NULL CHECK(version>=1),
    active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),
    payload_json TEXT NOT NULL,
    content_hash TEXT NOT NULL CHECK(length(content_hash)=64),
    created_at TEXT NOT NULL,
    superseded_at TEXT,
    PRIMARY KEY(genome_id, version)
);
