CREATE TABLE outcome_chains (
    chain_id TEXT PRIMARY KEY,
    mission_id TEXT NOT NULL,
    intended_outcome TEXT NOT NULL,
    state TEXT NOT NULL CHECK(state IN ('REGISTERED','IN_PROGRESS','BLOCKED','REALIZED','FAILED')),
    sustainment_required INTEGER NOT NULL DEFAULT 0 CHECK(sustainment_required IN (0,1)),
    payload_json TEXT NOT NULL,
    content_hash TEXT NOT NULL CHECK(length(content_hash)=64),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
