CREATE TABLE outcome_steps (
    step_id TEXT PRIMARY KEY,
    chain_id TEXT NOT NULL REFERENCES outcome_chains(chain_id) ON DELETE CASCADE,
    position INTEGER NOT NULL CHECK(position>=1),
    title TEXT NOT NULL,
    required INTEGER NOT NULL DEFAULT 1 CHECK(required IN (0,1)),
    state TEXT NOT NULL CHECK(state IN ('NOT_STARTED','IN_PROGRESS','EVIDENCE_PENDING','VERIFIED','BLOCKED','FAILED')),
    evidence_json TEXT NOT NULL,
    verification_json TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    UNIQUE(chain_id, position)
);
